head.script:
// 테스트 설명, 유효성 값 설정
//  - _3 : 처음 렌더링(emptyIndex) / 빈 값 상태에서 아이템 리스트 갱신(placeholder) 축
scwin.tData = {
    "description" : "[autoComplete > P > emptyItem]<br/>아이템 리스트에 없는 값이 설정되거나 입력되었을때 처리하는 방식을 설정합니다.",
    "validation" : [
        "컴포넌트가 처음 렌더링될 때 선택된 아이템이 없으면 emptyItem 속성과 관계없이 emptyIndex 속성에 설정된 인덱스의 아이템이 선택됩니다.",
        "처음 렌더링될 때 빈 값으로 표시하려면 emptyItem='true', emptyIndex='-1' 로 설정합니다.",
        "빈 값이 표시된 상태에서 아이템 리스트가 갱신되면 첫번째 아이템이 선택됩니다.",
        "단, placeholder 속성이 설정된 경우 빈 값이 표시된 상태에서 아이템 리스트가 갱신되어도 빈 값이 유지됩니다.",
    ]
}

// 처음 렌더링될 때의 아이템 / 갱신할 아이템
scwin.arrCity = [
    { "label" : "Seoul", "value" : "SEL" },
    { "label" : "Busan", "value" : "PUS" },
    { "label" : "Incheon", "value" : "ICN" },
    { "label" : "Jeju", "value" : "CJU" }
];
scwin.arrCityNew = [
    { "label" : "Gwangju", "value" : "KWJ" },
    { "label" : "Daejeon", "value" : "DJN" },
    { "label" : "Ulsan", "value" : "USN" }
];



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 아이템 DataList 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (emptyItem=true, emptyIndex=-1, placeholder 미설정)
    con_emptyItem.setValue("2");
    con_emptyIndex.setSelectedIndex(2);
    con_placeholder.setSelectedIndex(0);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (값을 설정하지 않아 처음 렌더링될 때 선택된 아이템이 없는 상태)
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- 처음 아이템 : Seoul / SEL, Busan / PUS, Incheon / ICN, Jeju / CJU (ref, 초기 값 설정 없음)\n- 아이템 리스트 갱신 : 아이템 DataList 를 Gwangju / KWJ, Daejeon / DJN, Ulsan / USN 으로 교체\n[절차]\n1. 조건 선택 -> Target 재생성 -> 상태 확인\n2. 빈 값이 표시된 상태에서 아이템 리스트 갱신 (결과 자동 출력)\n[확인] 선택 인덱스 / getValue / 표시값"', '', 'label1');

    // Target 재생성마다 처음 아이템으로 복원
    dlt_city.setJSON(scwin.arrCity);

    // 미설정 옵션은 속성 자체를 넣지 않는다 (createCList 가 빈값 키 제외, gdl_boolean 은 getText 로 읽는다)
    let properties = {
        emptyItem : con_emptyItem.getText(),
        emptyIndex : con_emptyIndex.getValue(),
        placeholder : con_placeholder.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
};



// 선택 인덱스 / getValue / 표시값 한 줄 출력
scwin.printState = function (strPrefix) {
    let labelElem = document.querySelector("[id='" + target1.id + "_label']");
    wf_body_bottom.getObj("scwin").setReturnValue(strPrefix + "선택 인덱스 : " + target1.getSelectedIndex() + " / getValue : " + target1.getValue() + " / 표시값 : '" + labelElem.textContent + "'");
};



// 처음 렌더링된 상태 출력 (validation 1, 2)
scwin.btn_getState_onclick = function (e) {
    scwin.printState("");
};



// 아이템 리스트 갱신 후 상태 출력 (validation 3, 4)
scwin.btn_refreshItem_onclick = function (e) {
    dlt_city.setJSON(scwin.arrCityNew);
    scwin.printState("아이템 리스트 갱신 -> ");
};
